package FSM::Support::ISFInterfacePortMetadata;

use strict;
use warnings;
use Carp qw(confess);
use Exporter 'import';
use Scalar::Util qw(refaddr);
use Storable qw(dclone);
use FSM::Package::AggregatePathSupport;

our @EXPORT_OK = qw(
    capture_interface_port_metadata
    snapshot_interface_port_metadata
    interface_port_metadata_contract
);

sub interface_port_metadata_contract {
    return {
        entry_keys => [qw(name direction width)],
        optional_entry_keys => [qw(type type_kind domain fields)],
        direction_values => [qw(input output)],
        type_kind_values => [qw(bit bits record)],
        field_keys => [qw(path width lsb msb signed)],
        optional_field_keys => ['state_model'],
        field_signed_values => [0, 1],
        field_state_model_values => [qw(two_state four_state)],
        shape => 'declared inputs in source order followed by declared outputs in source order; empty for a known empty interface; null when declaration metadata is unknown',
        field_layout => 'record scalar leaves in authored traversal order; port-relative member/item paths; first leaf most significant; inclusive packed ranges',
        meaning => 'declared ISF interface metadata; no inferred signals, private handoffs, source admission or hardware behavior is established by this projection',
    };
}

# The parser will supply its validated declarations. This producer is also
# tested on resolved record types before record source admission is enabled.
# It projects explicit properties rather than exporting parser/type objects.
sub capture_interface_port_metadata {
    my ($interface, $default_domain) = @_;
    return undef unless defined $interface;
    _require(ref($interface) eq 'HASH', 'expected declared interface');
    $interface = dclone($interface);
    _require(!defined($default_domain) || _identifier($default_domain), 'invalid default domain');
    my @ports;
    for my $pair (['inputs', 'input'], ['outputs', 'output']) {
        my ($key, $direction) = @$pair;
        _require(ref($interface->{$key}) eq 'ARRAY', "expected $key array");
        for my $port (@{$interface->{$key}}) {
            _require(ref($port) eq 'HASH', 'expected declared port');
            _require(_name($port->{name}), 'invalid declared port name');
            _require(_positive_integer($port->{width}), 'invalid declared port width');
            my %entry = (name => $port->{name}, direction => $direction, width => $port->{width});
            my $domain = defined($port->{domain}) ? $port->{domain} : $default_domain;
            $entry{domain} = $domain if defined $domain;
            if (exists $port->{type}) {
                $entry{type} = $port->{type};
                my $spec = $port->{type_spec};
                _require(ref($spec) eq 'HASH', "port '$port->{name}' lacks resolved type");
                my @paths;
                _collect_scalar_paths($spec, '', \@paths, {});
                _require(_positive_integer($port->{width}) && $port->{width} == $spec->{width},
                    "port '$port->{name}' type width disagrees");
                $entry{type_kind} = $spec->{kind};
                if ($spec->{kind} eq 'record') {
                    $entry{fields} = [map { _field_metadata($spec, $_) } @paths];
                } else {
                    _require($spec->{kind} eq 'bit' || $spec->{kind} eq 'bits',
                        "port '$port->{name}' unsupported root type");
                }
            } else {
                _require(!exists($port->{type_spec}), "port '$port->{name}' has type facts without an alias");
            }
            push @ports, \%entry;
        }
    }
    return snapshot_interface_port_metadata(\@ports);
}

sub _collect_scalar_paths {
    my ($spec, $path, $paths, $active) = @_;
    _require(ref($spec) eq 'HASH', 'invalid resolved member type');
    my $address = refaddr($spec);
    _require(!$active->{$address}, 'cyclic resolved type');
    local $active->{$address} = 1;
    _require(_positive_integer($spec->{width}), 'invalid resolved type width');
    my $kind = $spec->{kind} // '';
    if ($kind eq 'bit' || $kind eq 'bits') {
        _require($kind ne 'bit' || $spec->{width} == 1, 'bit type width must be one');
        _require(!exists($spec->{signed}) || _binary($spec->{signed}), 'invalid resolved signed property');
        _require(!exists($spec->{state_model}) || _state_model($spec->{state_model}), 'invalid resolved state model');
        push @$paths, $path;
        return;
    }
    my $width = 0;
    if ($kind eq 'record') {
        my ($members, $order) = @{$spec}{qw(members member_order)};
        _require(ref($members) eq 'HASH' && ref($order) eq 'ARRAY' && scalar(@$order),
            'record requires ordered members');
        _require(keys(%$members) == @$order, 'record member inventory disagrees');
        my %seen;
        for my $name (@$order) {
            _require(_identifier($name) && !$seen{$name}++ && exists($members->{$name}),
                'invalid or duplicate record member');
            _collect_scalar_paths($members->{$name}, "$path.$name", $paths, $active);
            $width += $members->{$name}{width};
        }
    } elsif ($kind eq 'list') {
        _require(length($path), 'list-root interface metadata remains unsupported');
        my $items = $spec->{items};
        _require(ref($items) eq 'ARRAY' && scalar(@$items), 'list requires ordered items');
        for my $index (0 .. $#$items) {
            _collect_scalar_paths($items->[$index], "$path\[$index\]", $paths, $active);
            $width += $items->[$index]{width};
        }
    } else {
        _require(0, 'unsupported resolved type kind');
    }
    _require($width == $spec->{width}, 'resolved aggregate width disagrees with members');
}

sub _field_metadata {
    my ($spec, $path) = @_;
    my $resolved = FSM::Package::AggregatePathSupport->resolve_packed_range(
        root_type_spec => $spec, path_text => $path,
    );
    _require($resolved->{ok}, 'declared record field has no packed range');
    my $leaf = $resolved->{type_spec};
    (my $relative_path = $path) =~ s/^\.//;
    my %field = (
        path => $relative_path, width => 0 + $resolved->{width},
        lsb => 0 + $resolved->{low}, msb => 0 + $resolved->{high},
        signed => ($leaf->{signed} // 0) ? 1 : 0,
    );
    $field{state_model} = $leaf->{state_model} if exists $leaf->{state_model};
    return \%field;
}

# Unknown provenance stays unknown. Known metadata is checked and rebuilt so
# each consumer receives a closed detached value, including nested fields.
sub snapshot_interface_port_metadata {
    my ($value) = @_;
    return undef unless defined $value;
    _require(ref($value) eq 'ARRAY', 'expected port metadata array');
    $value = dclone($value);
    my (@ports, %seen);
    my $outputs_started = 0;
    for my $port (@$value) {
        _require(ref($port) eq 'HASH', 'expected port metadata entry');
        _closed_keys($port, [qw(name direction width)], [qw(type type_kind domain fields)]);
        _require(_name($port->{name}) && !$seen{$port->{name}}++, 'invalid or duplicate port name');
        _require(defined($port->{direction}) && !ref($port->{direction})
            && scalar($port->{direction} =~ /\A(?:input|output)\z/), 'invalid direction');
        _require($port->{direction} ne 'input' || !$outputs_started, 'inputs must precede outputs');
        $outputs_started = 1 if $port->{direction} eq 'output';
        _require(_positive_integer($port->{width}), 'invalid port width');
        my %copy = (name => $port->{name}, direction => $port->{direction}, width => 0 + $port->{width});
        if (exists $port->{domain}) {
            _require(_identifier($port->{domain}), 'invalid domain');
            $copy{domain} = $port->{domain};
        }
        if (exists $port->{type}) {
            _require(defined($port->{type}) && !ref($port->{type})
                && scalar($port->{type} =~ /\A[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)?\z/), 'invalid type alias');
            _require(defined($port->{type_kind}) && !ref($port->{type_kind})
                && scalar($port->{type_kind} =~ /\A(?:bit|bits|record)\z/), 'invalid resolved type kind');
            _require($port->{type_kind} ne 'bit' || $port->{width} == 1, 'bit port width must be one');
            @copy{qw(type type_kind)} = @{$port}{qw(type type_kind)};
        } else {
            _require(!exists($port->{type_kind}) && !exists($port->{fields}), 'type facts require an alias');
        }
        if (($port->{type_kind} // '') eq 'record') {
            $copy{fields} = _snapshot_fields($port->{fields}, $port->{width});
        } else {
            _require(!exists($port->{fields}), 'scalar port cannot have record fields');
        }
        push @ports, \%copy;
    }
    return \@ports;
}

sub _snapshot_fields {
    my ($fields, $width) = @_;
    _require(ref($fields) eq 'ARRAY' && scalar(@$fields), 'record requires scalar field metadata');
    my (@copy, %seen);
    my $next_high = $width - 1;
    for my $field (@$fields) {
        _require(ref($field) eq 'HASH', 'expected scalar field entry');
        _closed_keys($field, [qw(path width lsb msb signed)], ['state_model']);
        my $path = $field->{path};
        _require(defined($path) && !ref($path)
            && $path =~ /\A[A-Za-z_]\w*(?:(?:\.[A-Za-z_]\w*)|(?:\[[0-9]+\]))*\z/
            && !$seen{$path}++, 'invalid or duplicate field path');
        _require(_positive_integer($field->{width}) && _nonnegative_integer($field->{lsb})
            && _nonnegative_integer($field->{msb}) && $field->{msb} == $next_high
            && $field->{msb} - $field->{lsb} + 1 == $field->{width}, 'field ranges do not form ordered packed layout');
        _require(_binary($field->{signed}), 'invalid scalar field signed property');
        my %entry = (path => $path, map { $_ => 0 + $field->{$_} } qw(width lsb msb signed));
        if (exists $field->{state_model}) {
            _require(_state_model($field->{state_model}), 'invalid scalar field state model');
            $entry{state_model} = $field->{state_model};
        }
        push @copy, \%entry;
        $next_high = $field->{lsb} - 1;
    }
    _require($next_high == -1, 'record field layout does not cover the port');
    return \@copy;
}

sub _closed_keys {
    my ($value, $required, $optional) = @_;
    my %allowed = map { $_ => 1 } (@$required, @$optional);
    _require(!grep(!exists($value->{$_}), @$required), 'missing metadata key');
    _require(!grep(!$allowed{$_}, keys %$value), 'unknown metadata key');
}

# Predicate results must be single values in argument-list context: a failed
# regex otherwise returns an empty list and shifts the diagnostic into slot 0.
sub _name { (defined($_[0]) && !ref($_[0]) && length($_[0])) ? 1 : 0 }
sub _identifier { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[A-Za-z_]\w*\z/) ? 1 : 0 }
sub _positive_integer { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[1-9][0-9]*\z/) ? 1 : 0 }
sub _nonnegative_integer { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A(?:0|[1-9][0-9]*)\z/) ? 1 : 0 }
sub _binary { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[01]\z/) ? 1 : 0 }
sub _state_model { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A(?:two_state|four_state)\z/) ? 1 : 0 }
sub _require {
    confess "Invalid ISF interface port metadata: validation requires a predicate and message\n"
        unless @_ == 2;
    confess "Invalid ISF interface port metadata: $_[1]\n" unless $_[0];
}

1;

perl/FSM/Support/ISFRecordPortContexts.p.body:
package FSM::Support::ISFRecordPortContexts;

use strict;
use warnings;
use Carp qw(confess);
use Exporter 'import';
use FSM::Support::ISFRecordPortScopes qw(record_context_scope record_reference_root_kind);
use FSM::Support::ISFRecordPortValues qw(record_value_scope record_value_reference validate_record_port_copy);
use FSM::Support::ISFRecordPortSamples qw(actor_has_record_port record_transaction_samples);

our @EXPORT_OK = qw(validate_actor_record_contexts);

# Parser and shared module admission use this resolved-reference gate. It does
# not replace the complete source grammar: existing validators own unknown
# tokens, arity, operators and namespace/static symbols; domain gates are separate.
sub validate_actor_record_contexts {
    my %args = @_;
    my %allowed = map {$_ => 1} qw(actor whole_output_writes_only);
    _require(!(grep {!$allowed{$_}} keys %args) && ref($args{actor}) eq 'HASH',
        'requires an actor map and supported context options');
    my $whole_only = exists($args{whole_output_writes_only}) ? $args{whole_output_writes_only} : 0;
    _require(defined($whole_only) && !ref($whole_only) && scalar($whole_only =~ /\A[01]\z/),
        'whole-output source-write policy must be binary');
    my $actor = $args{actor};
    my $scope = record_context_scope(actor => $actor);
    $scope->{whole_output_writes_only} = $whole_only;
    for my $tx (@{$actor->{transactions} || []}) {
        my $local = record_context_scope(actor => $actor, transaction => $tx);
        $local->{whole_output_writes_only} = $whole_only;
        if (actor_has_record_port(actor => $actor)) {
            my $samples = record_transaction_samples(actor => $actor, transaction => $tx, port_only => 1);
            $local->{roots} = record_value_scope(outer => $local->{roots}, local => $samples->{bindings});
        }
        _clauses($tx->{clauses}, $local, $actor, "transaction '$tx->{name}'");
    }
    for my $rule (@{$actor->{rules} || []}) {
        my $context = "rule '$rule->{name}'";
        _scalar($rule->{when}[1], $scope, "$context guard") if $rule->{when};
        for my $action (@{$rule->{actions} || []}) {
            my $head = $action->[0];
            if ($head eq 'set') {
                _assignment($action->[1], $action->[2], $scope, "$context assignment");
            } elsif ($head eq 'pulse') {
                _scalar_target($action->[1], $scope, "$context pulse target");
            } elsif ($head eq 'trigger') {
                _activation($action, $scope, "$context $head");
            } elsif ($head =~ /\A(?:atl_trigger|atl_trigger_batch|priority|store|load)\z/) {
                _unsupported($action, $scope, "$context $head");
            } else {
                _assignment($head, $action->[1], $scope, "$context assignment");
            }
        }
    }
    for my $name (sort keys %{$actor->{drives} || {}}) {
        my $drive = $actor->{drives}{$name};
        my $local = record_context_scope(actor => $actor, drive => $drive);
        $local->{whole_output_writes_only} = $whole_only;
        _drive_body($drive->{body}, $local, "drive '$name'");
    }
    return 1;
}

sub _clauses {
    my ($clauses, $scope, $actor, $context) = @_;
    for my $clause (@{$clauses || []}) {
        next unless ref($clause) eq 'ARRAY' && @$clause;
        my $head = $clause->[0];
        next unless defined($head) && !ref($head);
        if ($head eq 'set' || $head eq 'update') {
            _assignment($clause->[1], $clause->[2], $scope, "$context $head");
            _unsupported($_, $scope, "$context $head extra operand") for @{$clause}[3 .. $#$clause];
        } elsif ($head eq 'when' || $head eq 'while' || $head eq 'until') {
            _scalar($clause->[1], $scope, "$context $head condition");
            _clauses([@{$clause}[2 .. $#$clause]], $scope, $actor, "$context $head body");
        } elsif ($head eq 'repeat') {
            _unsupported($clause->[1], $scope, "$context repeat count");
            _clauses([@{$clause}[2 .. $#$clause]], $scope, $actor, "$context repeat body");
        } elsif ($head eq 'switch') {
            _scalar($clause->[1], $scope, "$context switch selector");
            for my $branch (@{$clause}[2 .. $#$clause]) {
                next unless ref($branch) eq 'ARRAY' && @$branch;
                _scalar($branch->[0], $scope, "$context switch branch value")
                    unless defined($branch->[0]) && !ref($branch->[0]) && $branch->[0] eq 'default';
                _clauses([@{$branch}[1 .. $#$branch]], $scope, $actor, "$context switch branch");
            }
        } elsif ($head eq 'drive') {
            my $name = $clause->[1];
            if (defined($name) && !ref($name) && exists(($actor->{drives} || {})->{$name})) {
                _scalar($_, $scope, "$context drive '$name' actual") for @{$clause}[2 .. $#$clause];
            } else {
                my $first = ref($name) eq 'ARRAY' ? 1 : 2;
                _drive_body([@{$clause}[$first .. $#$clause]], $scope, "$context inline drive");
            }
        } elsif ($head eq 'on') {
            _unsupported($clause->[1], $scope, "$context on trigger");
            _clauses([@{$clause}[2 .. $#$clause]], $scope, $actor, "$context on body");
        } elsif ($head eq 'spawn' || $head eq 'do') {
            _activation($clause, $scope, "$context $head clause");
        } elsif ($head eq 'sample' && actor_has_record_port(actor => $actor)) {
            # The ordered sample plan has already validated source paths, roles,
            # private aliases and exact scalar types. Existing source validators
            # still own placement; no capture assignment or state is introduced.
            next;
        } elsif ($head eq 'local' || $head eq 'params') {
            # Names/options are declarations, not expression operands. Existing
            # declaration/static-value validation remains authoritative.
            my $first = $head eq 'local' ? 2 : 1;
            for my $option (@{$clause}[$first .. $#$clause]) {
                next unless ref($option) eq 'ARRAY' && @$option >= 2;
                _unsupported($option->[1], $scope, "$context $head value");
            }
        } else {
            # No other source context inherits scalar-read permission here.
            _unsupported($clause, $scope, "$context $head clause");
        }
    }
}

sub _activation {
    my ($clause, $scope, $context) = @_;
    my $head = $clause->[0];
    my $first = $head eq 'spawn' ? 4 : 2;
    return _unsupported($clause, $scope, $context)
        unless @$clause >= $first && _identifier($clause->[1])
            && ($head ne 'spawn' || (defined($clause->[2]) && !ref($clause->[2])
                && $clause->[2] eq 'as' && _identifier($clause->[3])));
    # Target/instance, callee formal, parameter key and domain/timing names
    # are identities. Only actual values inherit the unsupported-record gate.
    # Complete grammar, endpoint, width and timing admission stay with their
    # existing owners; malformed/unknown forms retain the conservative scan.
    for my $option (@{$clause}[$first .. $#$clause]) {
        unless (ref($option) eq 'ARRAY' && @$option && defined($option->[0]) && !ref($option->[0])) {
            _unsupported($option, $scope, $context);
            next;
        }
        if ($option->[0] eq 'bind') {
            for my $entry (@{$option}[1 .. $#$option]) {
                unless (ref($entry) eq 'ARRAY' && @$entry >= 3
                    && defined($entry->[0]) && !ref($entry->[0])
                    && ($entry->[0] eq 'input' || $entry->[0] eq 'output') && _identifier($entry->[1])) {
                    _unsupported($entry, $scope, $context);
                    next;
                }
                _unsupported($entry->[2], $scope, $context);
                for my $extra (@{$entry}[3 .. $#$entry]) {
                    next if $entry->[0] eq 'input' && ref($extra) eq 'ARRAY' && @$extra == 2
                        && defined($extra->[0]) && !ref($extra->[0]) && $extra->[0] eq 'timing'
                        && defined($extra->[1]) && !ref($extra->[1]) && $extra->[1] =~ /\A(?:snapshot|live)\z/;
                    _unsupported($extra, $scope, $context);
                }
            }
        } elsif ($option->[0] eq 'params') {
            for my $entry (@{$option}[1 .. $#$option]) {
                _unsupported(ref($entry) eq 'ARRAY' && @$entry == 2 && _identifier($entry->[0])
                    ? $entry->[1] : $entry, $scope, $context);
            }
        } elsif ($option->[0] eq 'domain' && $head ne 'trigger' && @$option == 2 && _identifier($option->[1])) {
            next;
        } else {
            _unsupported($option, $scope, $context);
        }
    }
}

sub _identifier {return defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[A-Za-z_]\w*\z/;}

sub _drive_body {
    my ($body, $scope, $context) = @_;
    for my $entry (@{$body || []}) {
        next unless ref($entry) eq 'ARRAY' && @$entry >= 2;
        _assignment($entry->[0], $entry->[1], $scope, "$context assignment");
        _unsupported($_, $scope, "$context extra operand") for @{$entry}[2 .. $#$entry];
    }
}

sub _assignment {
    my ($target, $source, $scope, $context) = @_;
    my $to = _reference($target, $scope, 'write', "$context target");
    my $from = _reference($source, $scope, 'read', "$context RHS");
    return 1 if validate_record_port_copy(source => $from, target => $to, context => $context);
    _scalar($source, $scope, "$context RHS");
    return 1;
}

sub _scalar_target {
    my ($token, $scope, $context) = @_;
    my $value = _reference($token, $scope, 'write', $context);
    _require(!_whole_port($value), "$context requires a scalar target; '$token' is a whole record port");
}

sub _scalar {
    my ($expr, $scope, $context) = @_;
    return unless defined $expr;
    if (ref($expr) eq 'ARRAY') {
        return unless @$expr;
        # A state_active argument is a state identity, never a signal operand.
        return if defined($expr->[0]) && !ref($expr->[0]) && $expr->[0] eq 'state_active';
        my $operator = _reference($expr->[0], $scope, 'read', "$context operator");
        _require(!$operator || (!length($operator->{path_text}) && !_aggregate($operator->{type_spec})),
            "$context operator cannot use declared aggregate reference '$expr->[0]'");
        _scalar($_, $scope, $context) for @{$expr}[1 .. $#$expr];
        return;
    }
    return if ref($expr);
    # Preserve existing compact scalar conditions while preventing negation or
    # comparison spelling from hiding a whole record port in a scalar context.
    if ($expr =~ /\A(.+?)(?:==|!=|<=|>=|=|<|>)(.+)\z/) {
        my ($left, $right) = ($1, $2);
        _scalar($_, $scope, $context) for ($left, $right);
        return;
    }
    return _scalar($1, $scope, $context) if $expr =~ /\A!(.+)\z/;
    my $value = _reference($expr, $scope, 'read', $context);
    _require(!_whole_port($value), "$context requires a scalar value; '$expr' is a whole record port");
}

sub _unsupported {
    my ($value, $scope, $context) = @_;
    if (ref($value) eq 'ARRAY') {
        _unsupported($_, $scope, $context) for @$value;
        return;
    }
    return if !defined($value) || ref($value);
    if ($value =~ /\A(.+?)(?:==|!=|<=|>=|=|<|>)(.+)\z/) {
        my ($left, $right) = ($1, $2);
        _unsupported($_, $scope, $context) for ($left, $right);
        return;
    }
    return _unsupported($1, $scope, $context) if $value =~ /\A!(.+)\z/;
    my ($root) = $value =~ /\A([A-Za-z_]\w*)/;
    return unless defined($root) && exists($scope->{roots}{$root}) && _port_root($scope->{roots}{$root});
    _reference($value, $scope, 'read', $context); # validate paths before contextual refusal
    _require(0, "$context does not admit record port reference '$value'");
}

sub _reference {
    my ($token, $scope, $access, $context) = @_;
    return undef unless defined($token) && !ref($token) && $token =~ /\A([A-Za-z_]\w*)(.*)\z/s;
    my ($name, $suffix) = ($1, $2);
    my $roots = $scope->{roots};
    my $kind = record_reference_root_kind(context => $scope, token => $token);
    return undef unless defined($kind) && $kind eq 'declaration';
    return undef unless exists $roots->{$name};
    # Namespace tokens have already been delegated above. A declared drive
    # parameter is scalar-only; missing width facts cannot admit member access.
    _require(!($scope->{scalar_parameter_roots}{$name} && $suffix =~ /\A(?:\[[^\]]*\])*\./),
        "$context invalid declared path '$token': member_on_non_record");
    # A scalar pin can share an enum/package name. Those namespaces retain
    # their current validator unless a nearest aggregate, or an explicitly
    # shadowed outer aggregate, establishes this as a declaration path.
    # Scalar width/output annotations belong to the existing expression owner;
    # they cannot conceal a record port or an aggregate path here.
    return undef if length($suffix) && $suffix !~ /\A[.\[]/
        && !_aggregate($roots->{$name}{type_spec});
    my $value = record_value_reference(scope => $roots, token => $token, access => $access,
        allow_whole => 1, context => $context);
    # Prepared type/reference facts retain output members. Authored source
    # admission explicitly selects whole writes until field writers qualify.
    _require(!($scope->{whole_output_writes_only} && $access eq 'write' && $value
            && $value->{role} eq 'output' && length($value->{path_text})
            && _port_root($roots->{$name})),
        "$context record output field writes are not yet admitted; "
            . "target '$token' requires output-field writer qualification");
    return $value;
}
sub _aggregate {
    my ($spec) = @_;
    return (ref($spec) eq 'HASH' && ($spec->{kind} eq 'record' || $spec->{kind} eq 'list')) ? 1 : 0;
}
sub _port_root {
    my ($root) = @_;
    return (ref($root) eq 'HASH' && ($root->{role} eq 'input' || $root->{role} eq 'output')
        && ref($root->{type_spec}) eq 'HASH' && $root->{type_spec}{kind} eq 'record') ? 1 : 0;
}
sub _whole_port {
    my ($value) = @_;
    return (ref($value) eq 'HASH' && !length($value->{path_text}) && _port_root($value)) ? 1 : 0;
}
sub _require {
    confess "Invalid ISF record context: validation requires a predicate and message\n" unless @_ == 2;
    confess "Invalid ISF record context: $_[1]\n" unless $_[0];
}

1;

